-- Christmas 2026 products in the shop — Odette Confiserie
--
-- Generated by scripts/christmas-products-sql.mjs from src/data/christmas.js (do not edit by hand).
-- Run once in Supabase → SQL Editor, after the site with public/foto/craciun is live (the
-- photos). It is safe to run again. The site rebuilds by itself a few minutes later.
--
-- - Category "Produse de Crăciun" (the unused "Cutii de Craciun" one, renamed), first in the shop.
-- - 18 products, one per box size, in the order of the /craciun page. A product that already
--   exists with the same slug but is switched off is updated and switched on (its ingredients,
--   allergens and photo are kept); one that is already on is left as it is.
-- - Left out, already in the shop all year: Babka cu mac, Babka cu nucă, Babka cu fistic, Pachet Madeleine asortate, Sărățele cu semințe.
-- - Ingredients and allergens are empty: add them in the admin before customers order online.
--
-- After the holidays, switch the whole offer off with:
--   update public.products set "isActive" = false
--   where category = (select id from public.categories where slug = 'produse-de-craciun');

begin;

update public.categories
set name_ro = 'Produse de Crăciun', name_en = 'Christmas products', slug = 'produse-de-craciun', order_index = 0,
    intro_ro = 'Oferta de Crăciun și Revelion 2026. Comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.',
    intro_en = 'Our Christmas and New Year 2026 offer. Orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.'
where id = '8ac926ca-abc5-44dc-8c7d-5aae733e5844';

insert into public.categories (id, name_ro, name_en, slug, order_index, "isFeatured")
select gen_random_uuid(), 'Produse de Crăciun', 'Christmas products', 'produse-de-craciun', 0, false
where not exists (select 1 from public.categories where slug = 'produse-de-craciun');

insert into public.products as p
  (id, slug, name_ro, name_en, description_ro, description_en, price, price_unit, quantity,
   order_index, image_url, category, "isActive", best_seller_flag, "isVegetarian")
select gen_random_uuid(), v.slug, v.name_ro, v.name_en, v.description_ro, v.description_en, v.price, v.price_unit, v.quantity,
       v.order_index, v.image_url, (select id from public.categories where slug = 'produse-de-craciun'), true, false, false
from (values
    ('nostalgie-la-cutie-cutia-1', 'Nostalgie la cutie – Cutia 1', 'Nostalgia in a box – Box 1', 'Cutia preferată a tuturor clienților cărora le e poftă de prăjituri „ca pe vremuri”. Am folosit rețetele familiei mele din Maramureș și le-am adaptat cu tehnici profesionale și ingrediente premium pentru a obține un pachet perfect echilibrat. Conține: 8 choux cu vanilie, 6 Doboș, 6 Albinița, 6 Albă-ca-zăpada, 6 nuci cu ciocolată. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'The favourite box of every customer who craves “old-fashioned” cakes. We used my family’s recipes from Maramureș and adapted them with professional techniques and premium ingredients for a perfectly balanced box. Contents: 8 vanilla choux, 6 Dobos cakes, 6 Albinița honey cakes, 6 Albă-ca-zăpada (Snow White) cakes, 6 walnut cookies with chocolate. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 169, 'cutie', '1,08 kg · 32 buc', 1, 'https://www.odette-confiserie.ro/foto/craciun/nostalgie-la-cutie.webp'),
    ('nostalgie-la-cutie-cutia-2', 'Nostalgie la cutie – Cutia 2', 'Nostalgia in a box – Box 2', 'Cutia preferată a tuturor clienților cărora le e poftă de prăjituri „ca pe vremuri”. Am folosit rețetele familiei mele din Maramureș și le-am adaptat cu tehnici profesionale și ingrediente premium pentru a obține un pachet perfect echilibrat. Conține: 8 choux cu vanilie, 7 Doboș, 7 Albinița, 7 Albă-ca-zăpada, 12 nuci cu ciocolată. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'The favourite box of every customer who craves “old-fashioned” cakes. We used my family’s recipes from Maramureș and adapted them with professional techniques and premium ingredients for a perfectly balanced box. Contents: 8 vanilla choux, 7 Dobos cakes, 7 Albinița honey cakes, 7 Albă-ca-zăpada (Snow White) cakes, 12 walnut cookies with chocolate. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 209, 'cutie', '1,34 kg · 41 buc', 2, 'https://www.odette-confiserie.ro/foto/craciun/nostalgie-la-cutie.webp'),
    ('cutia-colindatorilor', 'Cutia colindătorilor', 'The carolers’ box', 'Acest asortiment e potrivit pentru a-ți încânta musafirii cu o selecție delicioasă de prăjituri făcute artizanal cu ingrediente de calitate la noi în laborator. Conține: 6 crinkle cookies, 11 linzere cu magiun de prune, 8 bucăți de ciocolată de casă, 8 brownie, 8 madeleine cu portocale. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'An assortment to delight your guests: a delicious selection of cakes, handmade from quality ingredients in our lab. Contents: 6 crinkle cookies, 11 linzer cookies with plum jam, 8 pieces of homemade chocolate, 8 brownies, 8 orange madeleines. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 189, 'cutie', '1,22 kg · 41 buc', 3, 'https://www.odette-confiserie.ro/foto/craciun/cutia-colindatorilor.webp'),
    ('cutia-aia', 'Cutia „Aia”', 'The “Aia” box', 'Știm cum e când ai musafiri de seamă și nu mai știi cu ce să îi impresionezi, așa că am pregătit Cutia „Aia” pentru musafirii „Ăia”… Conține: 4 Doboș, 4 macarons cu ciocolată cu lapte și alune, 4 mousse de ciocolată cu vișine și tonka, 4 madeleine cu portocale, ciocolată albă și fistic. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'We know how it is when important guests are coming and you have run out of ways to impress them, so we made “that” box (Cutia „Aia”) for “those” guests… Contents: 4 Dobos cakes, 4 milk chocolate and hazelnut macarons, 4 chocolate mousse cakes with sour cherries and tonka, 4 madeleines with orange, white chocolate and pistachio. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 99, 'cutie', '420 g · 16 buc', 4, 'https://www.odette-confiserie.ro/foto/craciun/cutia-aia.webp'),
    ('turn-de-madeleine', 'Turn de madeleine', 'Madeleine tower', 'Orice masă festivă are nevoie de un centerpiece, așa că am pregătit un aranjament de madeleine care să fure toate privirile: madeleine cu aromă de portocale, acoperite cu ciocolată albă Callebaut. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Every festive table needs a centrepiece, so we made a madeleine arrangement that steals the show: orange madeleines covered in Callebaut white chocolate. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 95, 'buc', '450 g', 5, 'https://www.odette-confiserie.ro/foto/craciun/turn-de-madeleine.webp'),
    ('babka-cu-ciocolata', 'Babka cu ciocolată', 'Chocolate babka', 'Aluat cu unt și ouă, dospit lent și împletit cu cremă de nucă, mac, ciocolată sau fistic. Cozonacul babka este cozonacul nostru de sărbători, iar pentru cei care țin la tradiție avem și cozonac clasic cu mac sau nucă. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Butter and egg dough, slowly proofed and braided with walnut, poppy seed, chocolate or pistachio cream. Babka is our holiday sweet bread, and for those who keep to tradition we also have the classic Romanian cozonac with poppy seeds or walnuts. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 80, 'buc', '700 g', 6, 'https://www.odette-confiserie.ro/foto/craciun/babka-cu-ciocolata.webp'),
    ('cozonac-cu-mac-sau-nuca', 'Cozonac cu mac sau nucă', 'Cozonac with poppy seeds or walnuts', 'Aluat cu unt și ouă, dospit lent și împletit cu cremă de nucă, mac, ciocolată sau fistic. Cozonacul babka este cozonacul nostru de sărbători, iar pentru cei care țin la tradiție avem și cozonac clasic cu mac sau nucă. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Butter and egg dough, slowly proofed and braided with walnut, poppy seed, chocolate or pistachio cream. Babka is our holiday sweet bread, and for those who keep to tradition we also have the classic Romanian cozonac with poppy seeds or walnuts. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 120, 'buc', '1 kg', 7, 'https://www.odette-confiserie.ro/foto/craciun/cozonac-cu-mac-sau-nuca.webp'),
    ('mini-babka-cu-ciocolata', 'Mini babka cu ciocolată', 'Mini chocolate babka', 'Aluat cu unt și ouă, dospit lent și împletit cu cremă de nucă, mac, ciocolată sau fistic. Cozonacul babka este cozonacul nostru de sărbători, iar pentru cei care țin la tradiție avem și cozonac clasic cu mac sau nucă. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Butter and egg dough, slowly proofed and braided with walnut, poppy seed, chocolate or pistachio cream. Babka is our holiday sweet bread, and for those who keep to tradition we also have the classic Romanian cozonac with poppy seeds or walnuts. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 20, 'buc', '150 g', 8, 'https://www.odette-confiserie.ro/foto/craciun/mini-babka-cu-ciocolata.webp'),
    ('linzere-cu-magiun-de-prune', 'Linzere cu magiun de prune', 'Linzer cookies with plum jam', 'Ambalate individual, în pachete de 100 g, 500 g sau 1 kg din fiecare. Prețul afișat este pentru 100 g. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Individually packed, in packs of 100 g, 500 g or 1 kg of each. The price shown is per 100 g. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 18, '100 g', 'pachete de 100 g, 500 g sau 1 kg', 9, 'https://www.odette-confiserie.ro/foto/craciun/linzere-cu-magiun-de-prune.webp'),
    ('nuci-cu-crema-de-ciocolata', 'Nuci cu cremă de ciocolată', 'Walnut cookies with chocolate cream', 'Ambalate individual, în pachete de 100 g, 500 g sau 1 kg din fiecare. Prețul afișat este pentru 100 g. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Individually packed, in packs of 100 g, 500 g or 1 kg of each. The price shown is per 100 g. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 17, '100 g', 'pachete de 100 g, 500 g sau 1 kg', 10, 'https://www.odette-confiserie.ro/foto/craciun/nuci-cu-crema-de-ciocolata.webp'),
    ('brownie-cu-peanut-butter', 'Brownie cu peanut butter', 'Peanut butter brownie', 'Ambalate individual, în pachete de 100 g, 500 g sau 1 kg din fiecare. Prețul afișat este pentru 100 g. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Individually packed, in packs of 100 g, 500 g or 1 kg of each. The price shown is per 100 g. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 17, '100 g', 'pachete de 100 g, 500 g sau 1 kg', 11, 'https://www.odette-confiserie.ro/foto/craciun/brownie-cu-peanut-butter.webp'),
    ('cosulete-cu-magiun-de-prune', 'Coșulețe cu magiun de prune', 'Plum jam tartlets', 'Ambalate individual, în pachete de 100 g, 500 g sau 1 kg din fiecare. Prețul afișat este pentru 100 g. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Individually packed, in packs of 100 g, 500 g or 1 kg of each. The price shown is per 100 g. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 16, '100 g', 'pachete de 100 g, 500 g sau 1 kg', 12, 'https://www.odette-confiserie.ro/foto/craciun/cosulete-cu-magiun-de-prune.webp'),
    ('ciocolata-de-casa-cu-migdale', 'Ciocolată de casă cu fulgi de migdale', 'Homemade chocolate with almond flakes', 'Ambalate individual, în pachete de 100 g, 500 g sau 1 kg din fiecare. Prețul afișat este pentru 100 g. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Individually packed, in packs of 100 g, 500 g or 1 kg of each. The price shown is per 100 g. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 16, '100 g', 'pachete de 100 g, 500 g sau 1 kg', 13, 'https://www.odette-confiserie.ro/foto/craciun/ciocolata-de-casa-cu-migdale.webp'),
    ('crinkle-cookies', 'Crinkle cookies', 'Crinkle cookies', 'Ambalate individual, în pachete de 100 g, 500 g sau 1 kg din fiecare. Prețul afișat este pentru 100 g. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Individually packed, in packs of 100 g, 500 g or 1 kg of each. The price shown is per 100 g. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 14, '100 g', 'pachete de 100 g, 500 g sau 1 kg', 14, 'https://www.odette-confiserie.ro/foto/craciun/crinkle-cookies.webp'),
    ('macarons-ciocolata-cu-lapte-si-alune', 'Macarons cu ganache de ciocolată cu lapte și alune', 'Macarons with milk chocolate and hazelnut ganache', 'Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 8, 'buc', null, 15, 'https://www.odette-confiserie.ro/foto/craciun/macarons-ciocolata-cu-lapte-si-alune.webp'),
    ('condimente-pentru-vin-fiert', 'Condimente pentru vin fiert', 'Mulled wine spices', 'Mici bucurii de iarnă, bune de pus lângă o cutie de prăjituri. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Little winter treats, just right next to a box of cakes. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 20, '100 g', null, 16, 'https://www.odette-confiserie.ro/foto/craciun/condimente-pentru-vin-fiert.webp'),
    ('caramel-sarat', 'Caramel sărat la borcan', 'Salted caramel in a jar', 'Mici bucurii de iarnă, bune de pus lângă o cutie de prăjituri. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Little winter treats, just right next to a box of cakes. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 19, 'borcan', '212 ml', 17, 'https://www.odette-confiserie.ro/foto/craciun/caramel-sarat.webp'),
    ('magiun-de-prune', 'Magiun de prune', 'Plum jam (magiun)', 'Mici bucurii de iarnă, bune de pus lângă o cutie de prăjituri. Din oferta de Crăciun: comenzi până pe 21 decembrie, cu ridicare sau livrare pe 23–24 decembrie sau 30–31 decembrie.', 'Little winter treats, just right next to a box of cakes. From our Christmas offer: orders until 21 December, with pickup or delivery on 23–24 December or 30–31 December.', 22, 'borcan', '400 g', 18, 'https://www.odette-confiserie.ro/foto/craciun/magiun-de-prune.webp')
  ) as v(slug, name_ro, name_en, description_ro, description_en, price, price_unit, quantity, order_index, image_url)
on conflict (slug) do update set
  name_ro = excluded.name_ro, name_en = excluded.name_en,
  description_ro = excluded.description_ro, description_en = excluded.description_en,
  price = excluded.price, price_unit = excluded.price_unit, quantity = excluded.quantity,
  order_index = excluded.order_index, image_url = coalesce(p.image_url, excluded.image_url),
  category = excluded.category, "isActive" = true
where not p."isActive";

commit;

-- Check: the offer as the shop will show it
select p.order_index, p.slug, p.name_ro, p.price, p.price_unit, p.quantity, p."isActive"
from public.products p
join public.categories c on c.id = p.category
where c.slug = 'produse-de-craciun'
order by p.order_index;
